# Path: tests/test_sovereign_sync.py\nfrom pathlib import Path\n\nfrom PC_ENGINE.sync.sovereign_sync import DEFAULT_ARTIFACTS, SovereignLearningSync, SyncConfig\n\ndef test_sync_is_disabled_by_default(tmp_path: Path):\n    sync = SovereignLearningSync(tmp_path, SyncConfig())\n    assert sync.enabled() is False\n    assert sync.status()["active"] is False\n\ndef test_collect_only_allows_curated_learning_artifacts(tmp_path: Path):\n    radar = tmp_path / "radar"\n    radar.mkdir()\n    (radar / "state_outcomes.jsonl").write_text('{"x":1}\n', encoding="utf-8")\n    (tmp_path / "runtime_state.json").write_text('{"secret":"no"}\n', encoding="utf-8")\n    sync = SovereignLearningSync(tmp_path, SyncConfig())\n    rows = sync._collect()\n    assert [row["artifact"] for row in rows] == ["radar/state_outcomes.jsonl"]\n    assert all(row["artifact"] in DEFAULT_ARTIFACTS for row in rows)\n\ndef test_status_persists_last_sync_state(tmp_path: Path):\n    sync = SovereignLearningSync(tmp_path, SyncConfig())\n    sync._write_state({"last_pull_ts": 123, "last_push_ts": 456, "last_error": None})\n    status = sync.status()\n    assert status["last_pull_ts"] == 123\n    assert status["last_push_ts"] == 456\n    assert status["last_error"] is None